        private void InitTrayIcon()
        {
            if (_notifyIcon != null)
            {
                // Already exists — ensure it's visible
                _notifyIcon.Visible = true;
                return;
            }

            _notifyIcon = new Forms.NotifyIcon
            {
                Text    = "SMD Win",
                Visible = true,  // Always show tray icon
            };

            // Load the app .ico from embedded resource
            try
            {
                var uri = new Uri("pack://application:,,,/Assets/smdwin.ico");
                var info = System.Windows.Application.GetResourceStream(uri);
                if (info != null)
                    _notifyIcon.Icon = new System.Drawing.Icon(info.Stream);
                else
                    _notifyIcon.Icon = System.Drawing.SystemIcons.Application;
            }
            catch
            {
                _notifyIcon.Icon = System.Drawing.SystemIcons.Application;
            }

            // Double-click → restore
            _notifyIcon.DoubleClick += (_, _) => RestoreFromTray();
            // Single click → also restore
            _notifyIcon.Click += (_, e) =>
            {
                if (e is System.Windows.Forms.MouseEventArgs me && me.Button == System.Windows.Forms.MouseButtons.Left)
                    RestoreFromTray();
            };

            // Context menu — modern dark style
            var menu = new Forms.ContextMenuStrip();
            menu.Renderer = new TrayMenuRenderer();
            menu.BackColor = System.Drawing.Color.FromArgb(16, 20, 32);
            menu.ForeColor = System.Drawing.Color.FromArgb(210, 215, 230);
            menu.ShowImageMargin = false;
            menu.Font = new System.Drawing.Font("Segoe UI", 9f);
            menu.Padding = new System.Windows.Forms.Padding(8, 12, 8, 12);

            const int TrayItemW = 220;

            var headerItem = new Forms.ToolStripMenuItem("SMD Win");
            headerItem.Font = new System.Drawing.Font("Segoe UI", 8.5f);
            headerItem.ForeColor = System.Drawing.Color.FromArgb(90, 120, 160);
            headerItem.Padding = new System.Windows.Forms.Padding(0, 10, 0, 10);
            headerItem.AutoSize = false;
            headerItem.Width = TrayItemW;
            headerItem.TextAlign = System.Drawing.ContentAlignment.MiddleCenter;
            headerItem.Enabled = false;

            var openItem = new Forms.ToolStripMenuItem("⊞    Open SMD Win");
            openItem.Font = new System.Drawing.Font("Segoe UI", 9.5f, System.Drawing.FontStyle.Bold);
            openItem.ForeColor = System.Drawing.Color.FromArgb(235, 240, 255);
            openItem.Padding = new System.Windows.Forms.Padding(4, 14, 0, 14);
            openItem.AutoSize = false;
            openItem.Width = TrayItemW;
            openItem.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
            openItem.Click += (_, _) => RestoreFromTray();

            var widgetItem = new Forms.ToolStripMenuItem("⧉    Toggle Widget");
            widgetItem.Font = new System.Drawing.Font("Segoe UI", 9f);
            widgetItem.ForeColor = System.Drawing.Color.FromArgb(200, 210, 230);
            widgetItem.Padding = new System.Windows.Forms.Padding(4, 14, 0, 14);
            widgetItem.AutoSize = false;
            widgetItem.Width = TrayItemW;
            widgetItem.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
            widgetItem.Click += (_, _) =>
            {
                _ = Dispatcher.InvokeAsync(() =>
                {
                    // Close whichever widget is open, or open via the unified toggle
                    if (_compactWidget != null && _compactWidget.IsVisible)
                    {
                        _compactWidget.Close();
                        _compactWidget = null;
                        UpdateWidgetCaptionIndicator();
                    }
                    else
                    {
                        BtnToggleWidget_Click(this, new RoutedEventArgs());
                    }
                });
            };

            var exitItem = new Forms.ToolStripMenuItem("✕    Exit");
            exitItem.Font = new System.Drawing.Font("Segoe UI", 9f);
            exitItem.Padding = new System.Windows.Forms.Padding(4, 14, 0, 14);
            exitItem.AutoSize = false;
            exitItem.Width = TrayItemW;
            exitItem.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
            exitItem.ForeColor = System.Drawing.Color.FromArgb(239, 68, 68);
            exitItem.Click += (_, _) =>
            {
                _isClosingToTray = true;
                _notifyIcon?.Dispose();
                Application.Current.Shutdown();
                // Force-kill any lingering background threads (WMI, perf counters) after 2s
                Task.Delay(2000).ContinueWith(_ => Environment.Exit(0));
            };

            Forms.ToolStripMenuItem MakeItem(string text)
            {
                var it = new Forms.ToolStripMenuItem(text);
                it.Font = new System.Drawing.Font("Segoe UI", 9f);
                it.ForeColor = System.Drawing.Color.FromArgb(200, 210, 230);
                it.Padding = new System.Windows.Forms.Padding(4, 14, 0, 14);
                it.AutoSize = false;
                it.Width = TrayItemW;
                it.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
                return it;
            }

            var settingsItem = MakeItem("⚙    Settings");
            settingsItem.Click += (_, _) =>
            {
                _ = Dispatcher.InvokeAsync(async () =>
                {
                    RestoreFromTray();
                    await NavigateTo("Settings");
                });
            };

            var sensorsMenu = MakeItem("🌡    Sensors");

            var masterToggle = MakeItem("Show Sensors in Tray");
            masterToggle.CheckOnClick = true;
            masterToggle.Checked = SettingsService.Current.TraySensorsEnabled;
            masterToggle.Click += (_, _) =>
            {
                SettingsService.Current.TraySensorsEnabled = masterToggle.Checked;
                SettingsService.Save();
                try { RebuildTraySensorIcons(); }
                catch (Exception ex) { AppLogger.Debug($"TrayMenu.ToggleTraySensors: {ex.Message}"); }
            };
            sensorsMenu.DropDownItems.Add(masterToggle);
            sensorsMenu.DropDownItems.Add(new Forms.ToolStripSeparator());

            var activeMetrics = GetActiveTraySensorMetrics();
            // A stable order, more readable than the raw HashSet order.
            string[] metricOrder = AllLiveMetrics;

            foreach (var metric in metricOrder)
            {
                var showToggle = MakeItem(TraySensorLabel(metric));
                showToggle.CheckOnClick = true;
                showToggle.Checked = activeMetrics.Contains(metric);
                showToggle.Click += (_, _) =>
                {
                    SetTraySensorMetricEnabled(metric, showToggle.Checked);
                    try { RebuildTraySensorIcons(); }
                    catch (Exception ex) { AppLogger.Debug($"TrayMenu.ToggleMetric({metric}): {ex.Message}"); }
                    // Settings shows the same list — keep it in sync with the tray menu
                    try { Dispatcher.BeginInvoke(new Action(BuildMetricsMatrix)); } catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
                };
                sensorsMenu.DropDownItems.Add(showToggle);
            }

            menu.Items.Add(headerItem);
            menu.Items.Add(new Forms.ToolStripSeparator());
            menu.Items.Add(openItem);
            menu.Items.Add(widgetItem);
            menu.Items.Add(new Forms.ToolStripSeparator());
            menu.Items.Add(sensorsMenu);
            menu.Items.Add(settingsItem);
            menu.Items.Add(new Forms.ToolStripSeparator());
            menu.Items.Add(exitItem);
            _notifyIcon.ContextMenuStrip = menu;
        }

        /// <summary>Generates a small bitmap filled with a colour — used as the Image on the entries of the colour submenu
        /// (a visual swatch, not just text).</summary>
        private static System.Drawing.Bitmap MakeSwatchBitmap(System.Drawing.Color color)
        {
            var bmp = new System.Drawing.Bitmap(14, 14);
            using (var g = System.Drawing.Graphics.FromImage(bmp))
            using (var brush = new System.Drawing.SolidBrush(color))
                g.FillEllipse(brush, 1, 1, 12, 12);
            return bmp;
        }

        // all widget metrics can appear in the tray too.
        // The speeds (network / disk) and the battery time have compact text on the icon ("850K", "1.2M", "2:15"),
        // and the full value in the tooltip.
        private static readonly HashSet<string> TrayEligibleMetrics = new()
        { "CPU", "CPUFreq", "CPUTemp", "GPU", "GPUTemp", "RAM", "Battery", "BatteryTime", "NetUp", "NetDown", "DiskRead", "DiskWrite" };

        private static readonly HashSet<string> LegacyTrayEligibleMetrics = new()
        { "CPU", "CPUFreq", "CPUTemp", "GPU", "GPUTemp", "RAM", "Battery" };

        /// <summary>Ordinea comuna a metricilor (Settings, meniul tray, iconite).</summary>
        internal static readonly string[] AllLiveMetrics =
        { "CPUTemp", "CPU", "CPUFreq", "GPUTemp", "GPU", "RAM", "Battery", "BatteryTime", "NetDown", "NetUp", "DiskRead", "DiskWrite" };
        private const int MaxTraySensorIcons = 8;

        private static readonly (string Name, WpfColor Color)[] TraySensorPalette =
        {
            ("Red",    WpfColor.FromRgb(0xEF, 0x44, 0x44)),
            ("Orange", WpfColor.FromRgb(0xF9, 0x73, 0x16)),
            ("Amber",  WpfColor.FromRgb(0xF5, 0x9E, 0x0B)),
            ("Yellow", WpfColor.FromRgb(0xEA, 0xB3, 0x08)),
            ("Green",  WpfColor.FromRgb(0x22, 0xC5, 0x5E)),
            ("Teal",   WpfColor.FromRgb(0x14, 0xB8, 0xA6)),
            ("Cyan",   WpfColor.FromRgb(0x06, 0xB6, 0xD4)),
            ("Blue",   WpfColor.FromRgb(0x3B, 0x82, 0xF6)),
            ("Purple", WpfColor.FromRgb(0xA8, 0x55, 0xF7)),
            ("Pink",   WpfColor.FromRgb(0xEC, 0x48, 0x99)),
        };

        /// <summary>Reads the metric→colour map from Settings.TraySensorColors (CSV "METRIC=#RRGGBB;..."). A missing metric or
        /// "Dynamic" means the default behaviour (gradient/thresholds), not a fixed colour.</summary>
        private static Dictionary<string, string> ParseTraySensorColors()
        {
            var map = new Dictionary<string, string>();
            string csv = SettingsService.Current.TraySensorColors ?? "";
            foreach (var pair in csv.Split(';', StringSplitOptions.RemoveEmptyEntries))
            {
                var kv = pair.Split('=', 2);
                if (kv.Length == 2) map[kv[0]] = kv[1];
            }
            return map;
        }

        private static void SaveTraySensorColor(string metric, string? hexOrNull)
        {
            var map = ParseTraySensorColors();
            if (string.IsNullOrEmpty(hexOrNull) || hexOrNull == "Dynamic") map.Remove(metric);
            else map[metric] = hexOrNull;
            SettingsService.Current.TraySensorColors = string.Join(";", map.Select(kv => $"{kv.Key}={kv.Value}"));
            SettingsService.Save();
        }

        /// <summary>The list of active tray metrics — TraySensorMetricsOverride if it was ever set from the tray menu, otherwise
        /// the default behaviour (WidgetCompactMetrics ∩ TrayEligibleMetrics), for compatibility with existing installs.</summary>
        private static string[] GetActiveTraySensorMetrics()
        {
            string? overrideCsv = SettingsService.Current.TraySensorMetricsOverride;
            if (overrideCsv != null)
                return overrideCsv.Split(',', StringSplitOptions.RemoveEmptyEntries)
                                   .Where(m => TrayEligibleMetrics.Contains(m)).Distinct().Take(MaxTraySensorIcons).ToArray();

            // Without its own tray list: the default behaviour, with the OLD set of eligible metrics — otherwise the network/disk
            // icons from the widget would suddenly appear in the tray too.
            string csv = SettingsService.Current.WidgetCompactMetrics ?? "";
            return csv.Split(',', StringSplitOptions.RemoveEmptyEntries)
                       .Where(m => LegacyTrayEligibleMetrics.Contains(m)).Distinct().Take(MaxTraySensorIcons).ToArray();
        }

        private static void SetTraySensorMetricEnabled(string metric, bool enabled)
        {
            var current = GetActiveTraySensorMetrics().ToList();
            if (enabled) { if (!current.Contains(metric)) current.Add(metric); }
            else current.Remove(metric);
            SettingsService.Current.TraySensorMetricsOverride = string.Join(",", current);
            SettingsService.Save();
        }

        private readonly Dictionary<string, Forms.NotifyIcon> _traySensorIcons = new();
        private Dictionary<string, string> _traySensorColorOverrides = new();

        private readonly Dictionary<string, (float Min, float Max, double Sum, int Count)> _trayMetricStats = new();
        private static readonly HashSet<string> TrayStatsMetrics = new() { "CPUTemp", "GPUTemp", "CPUFreq" };

        /// <summary>Updates min/max/avg for an eligible metric (temp/freq). Ignores missing or <=0 reads (sensor unavailable), so
        /// a false zero does not spoil the minimum.</summary>
        private void UpdateTrayStat(string metric, float? value)
        {
            if (!TrayStatsMetrics.Contains(metric) || !value.HasValue || value.Value <= 0) return;
            float v = value.Value;
            if (_trayMetricStats.TryGetValue(metric, out var s))
                _trayMetricStats[metric] = (Math.Min(s.Min, v), Math.Max(s.Max, v), s.Sum + v, s.Count + 1);
            else
                _trayMetricStats[metric] = (v, v, v, 1);
        }

        /// <summary>The " · min X / avg Y / max Z" suffix for the tooltip, or "" if the metric has no statistics (yet) or is not
        /// eligible. Formatted like the main value (° for temp, G/M for freq), so it does not look like a different unit on hover.</summary>
        private string TrayStatsSuffix(string metric)
        {
            if (!_trayMetricStats.TryGetValue(metric, out var s) || s.Count == 0) return "";
            float avg = (float)(s.Sum / s.Count);
            string Fmt(float v) => metric == "CPUFreq"
                ? (v >= 1000 ? $"{v / 1000f:F1}G" : $"{v:F0}M")
                : $"{TempUnit.Deg(v)}";
            return $"  ·  min {Fmt(s.Min)} / avg {Fmt(avg)} / max {Fmt(s.Max)}";
        }

        // NOTE: DestroyIcon(IntPtr) is already declared further down in the file (used by other existing code) — redeclaring it
        // here gives CS0111. That declaration is reused.

        /// <summary>Recreates the tray icons after the on/off setting or the metric list (WidgetCompactMetrics) changed. Called at
        /// start, on the Settings toggle, and from the Widget / Tray matrix (OnMetricsMatrixChanged) when the list changes.</summary>
        private static readonly System.Diagnostics.Stopwatch _appStartStopwatch = System.Diagnostics.Stopwatch.StartNew();
        private void RebuildTraySensorIcons()
        {
            DisposeTraySensorIcons();

            if (!SettingsService.Current.TraySensorsEnabled) return;

            var metrics = GetActiveTraySensorMetrics();
            _traySensorColorOverrides = ParseTraySensorColors();
            AppLogger.Info($"S-DIAG TraySensors: rebuild started at +{_appStartStopwatch.ElapsedMilliseconds}ms, {metrics.Length} metrics: {string.Join(",", metrics)}");

            foreach (var metric in metrics)
            {
                try
                {
                    var placeholder = RenderSensorIcon("--", WpfColor.FromRgb(0xEA, 0xEA, 0xEA));
                    var ni = new Forms.NotifyIcon { Icon = placeholder, Text = metric };
                    ni.Visible = true;

                    // Left click -> restore the window and navigate to the sensor's page (the same behaviour as the widget). "metric" is
                    // captured correctly per iteration (C# 5+ captures per iteration in foreach, not shared).
                    string metricForClick = metric;
                    ni.Click += (_, e) =>
                    {
                        if (e is Forms.MouseEventArgs me && me.Button == Forms.MouseButtons.Left)
                            NavigateFromTraySensor(metricForClick);
                    };

                    ni.ContextMenuStrip = BuildTraySensorContextMenu(metricForClick);

                    _traySensorIcons[metric] = ni;
                }
                catch (Exception ex) { AppLogger.Warning(ex, $"RebuildTraySensorIcons({metric})"); }
            }
            AppLogger.Info($"S-DIAG TraySensors: {_traySensorIcons.Count}/{metrics.Length} icons created at +{_appStartStopwatch.ElapsedMilliseconds}ms");
        }

        private Forms.ContextMenuStrip BuildTraySensorContextMenu(string metric)
        {
            var menu = new Forms.ContextMenuStrip();
            menu.Renderer = new TrayMenuRenderer();
            menu.BackColor = System.Drawing.Color.FromArgb(16, 20, 32);
            menu.ForeColor = System.Drawing.Color.FromArgb(210, 215, 230);
            menu.ShowImageMargin = false;
            menu.Font = new System.Drawing.Font("Segoe UI", 9f);
            menu.Padding = new System.Windows.Forms.Padding(8, 12, 8, 12);

            Forms.ToolStripMenuItem MakeItem(string text)
            {
                var it = new Forms.ToolStripMenuItem(text);
                it.Font = new System.Drawing.Font("Segoe UI", 9f);
                it.ForeColor = System.Drawing.Color.FromArgb(200, 210, 230);
                it.Padding = new System.Windows.Forms.Padding(4, 10, 0, 10);
                it.AutoSize = false;
                it.Width = 200;
                it.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
                return it;
            }

            var headerItem = new Forms.ToolStripMenuItem(TraySensorLabel(metric)) { Enabled = false };
            menu.Items.Add(headerItem);
            menu.Items.Add(new Forms.ToolStripSeparator());

            var openItem = MakeItem("⊞    Open SMD Win");
            openItem.Click += (_, _) => RestoreFromTray();
            menu.Items.Add(openItem);

            var colorHeader = new Forms.ToolStripMenuItem("Color") { Enabled = false };
            menu.Items.Add(new Forms.ToolStripSeparator());
            menu.Items.Add(colorHeader);

            var colorMap = ParseTraySensorColors();
            bool hasOverride = colorMap.ContainsKey(metric);
            var dynamicItem = new Forms.ToolStripMenuItem("Dynamic (default)")
            { Checked = !hasOverride, CheckOnClick = false };
            menu.Items.Add(dynamicItem);

            var allColorItems = new System.Collections.Generic.List<Forms.ToolStripMenuItem> { dynamicItem };

            foreach (var (name, wpfColor) in TraySensorPalette)
            {
                string hex = $"#{wpfColor.R:X2}{wpfColor.G:X2}{wpfColor.B:X2}";
                bool isChecked = hasOverride && string.Equals(colorMap[metric], hex, StringComparison.OrdinalIgnoreCase);
                var colorItem = new Forms.ToolStripMenuItem(name)
                {
                    Checked = isChecked, CheckOnClick = false,
                    Image = MakeSwatchBitmap(System.Drawing.Color.FromArgb(wpfColor.R, wpfColor.G, wpfColor.B)),
                };
                allColorItems.Add(colorItem);
                menu.Items.Add(colorItem);
            }

            dynamicItem.Click += (_, _) =>
            {
                SaveTraySensorColor(metric, null);
                _traySensorColorOverrides = ParseTraySensorColors();
                foreach (var it in allColorItems) it.Checked = (it == dynamicItem);
            };
            foreach (var it in allColorItems.Skip(1))
            {
                it.Click += (_, _) =>
                {
                    var (_, wpfColor) = TraySensorPalette.First(p => p.Name == it.Text);
                    string hex = $"#{wpfColor.R:X2}{wpfColor.G:X2}{wpfColor.B:X2}";
                    SaveTraySensorColor(metric, hex);
                    _traySensorColorOverrides = ParseTraySensorColors();
                    foreach (var other in allColorItems) other.Checked = (other == it);
                };
            }

            menu.Items.Add(new Forms.ToolStripSeparator());
            var exitItem = MakeItem("✕    Exit");
            exitItem.ForeColor = System.Drawing.Color.FromArgb(239, 68, 68);
            exitItem.Click += (_, _) =>
            {
                _isClosingToTray = true;
                _notifyIcon?.Dispose();
                Application.Current.Shutdown();
                Task.Delay(2000).ContinueWith(_ => Environment.Exit(0));
            };
            menu.Items.Add(exitItem);

            return menu;
        }

        private void DisposeTraySensorIcons()
        {
            foreach (var kv in _traySensorIcons)
            {
                try { kv.Value.Visible = false; kv.Value.Icon?.Dispose(); kv.Value.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }
            _traySensorIcons.Clear();
        }

        /// <summary>Called from the same tick that feeds the compact widget (OnTempTick). Uses the values already computed in the
        /// tick — does not re-read the sensors.</summary>
        private readonly HashSet<string> _trayFirstValueLogged = new();
        private void UpdateTraySensorIcons(float cpuPct, float gpuPct, float ramPct,
            float? cpuTemp, float? gpuTemp, float? cpuFreqMHz)
        {
            if (_traySensorIcons.Count == 0) { UpdateTrayPreview(null); return; }
            var preview = new List<(string text, WpfColor color, string label)>();   // the preview in Settings

            UpdateTrayStat("CPUTemp", cpuTemp);
            UpdateTrayStat("GPUTemp", gpuTemp);
            UpdateTrayStat("CPUFreq", cpuFreqMHz);

            foreach (var kv in _traySensorIcons)
            {
                string metric = kv.Key;
                Forms.NotifyIcon ni = kv.Value;
                (string text, WpfColor color) = TraySensorMetricValue(metric, cpuPct, gpuPct, ramPct, cpuTemp, gpuTemp, cpuFreqMHz);

                if (_traySensorColorOverrides.TryGetValue(metric, out var fixedHex))
                {
                    try { color = (WpfColor)WpfColorConv.ConvertFromString(fixedHex)!; }
                    catch (Exception ex) { AppLogger.Debug($"TraySensorColor override parse '{fixedHex}': {ex.Message}"); }
                }

                if (text != "--" && _trayFirstValueLogged.Add(metric))
                    AppLogger.Info($"S-DIAG TraySensors: {metric} first real value ({text}) at +{_appStartStopwatch.ElapsedMilliseconds}ms");

                try
                {
                    // on the icon render WITHOUT the unit (% / °) — see StripUnitForIcon; the tooltip ("SMD Win — CPU Temp: 42°") keeps the
                    // full text, where space is not a problem.
                    string iconText = StripUnitForIcon(metric, text);
                    preview.Add((iconText, color, $"{TraySensorLabel(metric)}: {text}"));
                    var newIcon = RenderSensorIcon(iconText, color, metric);
                    var oldIcon = ni.Icon;

                    ni.Icon = newIcon;
                    ni.Text = ($"{TraySensorLabel(metric)}: {text}{TrayStatsSuffix(metric)}");

                    oldIcon?.Dispose(); // the old icon was a self-owned Clone() — Dispose() correctly releases the GDI handle
                }
                catch (Exception ex) { AppLogger.Warning(ex, $"UpdateTraySensorIcons({metric})"); }
            }
            UpdateTrayPreview(preview);
        }

        private static string TraySensorLabel(string metric) => metric switch
        {
            "CPU" => "CPU", "CPUFreq" => "CPU Freq", "CPUTemp" => "CPU Temp",
            "GPU" => "GPU", "GPUTemp" => "GPU Temp", "RAM" => "RAM", "Battery" => "Battery",
            "BatteryTime" => "Battery time", "NetUp" => "Upload", "NetDown" => "Download",
            "DiskRead" => "Disk read", "DiskWrite" => "Disk write",
            _ => metric
        };

        /// <summary>Click on a tray icon -> restore the window and navigate to that sensor's page, as a click in the widget does.</summary>
        private void NavigateFromTraySensor(string metric)
        {
            try
            {
                RestoreFromTray();
                Button? target = metric switch
                {
                    "CPU" or "GPU" or "CPUTemp" or "GPUTemp" or "CPUFreq" => BtnStress,
                    "RAM" => BtnRam,
                    "Battery" => BtnBattery,
                    _ => null
                };
                if (target != null) NavBtn_Click(target, new RoutedEventArgs());
            }
            catch (Exception ex) { AppLogger.Debug($"NavigateFromTraySensor({metric}): {ex.Message}"); }
        }

        private static readonly WpfColor _trayWarnColor = WpfColor.FromRgb(0xC2, 0x65, 0x0A);
        private static readonly WpfColor _trayHotColor  = WpfColor.FromRgb(0xFF, 0x5A, 0x5A);

        private (string text, WpfColor color) TraySensorMetricValue(string metric,
            float cpuPct, float gpuPct, float ramPct, float? cpuTemp, float? gpuTemp, float? cpuFreqMHz)
        {
            var normal = WpfColor.FromRgb(0xEA, 0xEA, 0xEA);
            var warn   = _trayWarnColor;
            var hot    = _trayHotColor;

            switch (metric)
            {
                case "CPU":
                    if (cpuPct < 0) return ("--", normal);
                    return ($"{cpuPct:F0}%", cpuPct >= 85 ? hot : cpuPct >= 70 ? warn : normal);
                case "GPU":
                    if (gpuPct < 0) return ("--", normal);
                    return ($"{gpuPct:F0}%", gpuPct >= 85 ? hot : gpuPct >= 70 ? warn : normal);
                case "RAM":
                    if (ramPct < 0) return ("--", normal);
                    return ($"{ramPct:F0}%", ramPct >= 85 ? hot : ramPct >= 70 ? warn : normal);
                case "CPUTemp":
                    if (!cpuTemp.HasValue) return ("--", normal);
                    return ($"{TempUnit.Deg(cpuTemp.Value)}", TempColorGradient(cpuTemp.Value));
                case "GPUTemp":
                    if (!gpuTemp.HasValue) return ("--", normal);
                    return ($"{TempUnit.Deg(gpuTemp.Value)}", TempColorGradient(gpuTemp.Value, isGpu: true));
                case "CPUFreq":
                    if (!cpuFreqMHz.HasValue) return ("--", normal);
                    return (cpuFreqMHz.Value >= 1000 ? $"{cpuFreqMHz.Value / 1000f:F1}G" : $"{cpuFreqMHz.Value:F0}M", normal);
                case "Battery":
                    try
                    {
                        var ps = Forms.SystemInformation.PowerStatus;
                        bool hasBat = ps.BatteryChargeStatus != Forms.BatteryChargeStatus.NoSystemBattery;
                        if (!hasBat) return ("AC", normal);
                        float pct = ps.BatteryLifePercent * 100f;
                        return ($"{pct:F0}%", pct < 20 ? hot : pct < 40 ? warn : normal);
                    }
                    catch { return ("--", normal); }
                case "BatteryTime":
                    try
                    {
                        var ps = Forms.SystemInformation.PowerStatus;
                        bool hasBat = ps.BatteryChargeStatus != Forms.BatteryChargeStatus.NoSystemBattery;
                        int secs = ps.BatteryLifeRemaining;
                        if (!hasBat || secs < 0 || ps.PowerLineStatus == Forms.PowerLineStatus.Online)
                        { _trayIconText[metric] = "AC"; return ("AC", normal); }
                        _trayIconText[metric] = $"{secs / 3600}:{(secs % 3600) / 60:D2}";
                        return ($"{secs / 3600}h {(secs % 3600) / 60:D2}min", secs < 1200 ? hot : secs < 2400 ? warn : normal);
                    }
                    catch { return ("--", normal); }
                case "NetUp":
                case "NetDown":
                case "DiskRead":
                case "DiskWrite":
                {
                    float kbps = metric switch
                    {
                        "NetUp"   => _emaNetUp,
                        "NetDown" => _emaNetDown,
                        "DiskRead"  => _dashDiskRead[(_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints],
                        _           => _dashDiskWrite[(_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints],
                    };
                    if (float.IsNaN(kbps) || kbps < 0) return ("--", normal);
                    _trayIconText[metric] = CompactRate(kbps);
                    string full = kbps >= 1048576f ? $"{kbps / 1048576f:F2} GB/s"
                                : kbps >= 1024f    ? $"{kbps / 1024f:F1} MB/s"
                                :                    $"{kbps:F0} KB/s";
                    return (full, normal);
                }
                default:
                    return ("--", normal);
            }
        }

        // Compact text for the icon (max ~4 characters) for the metrics whose full text does not fit: the speeds and the battery
        // time. Filled in TraySensorMetricValue.
        private readonly Dictionary<string, string> _trayIconText = new();

        private static string CompactRate(float kbps)
        {
            if (kbps < 1000f)     return $"{kbps:F0}K";               // 0K … 999K
            float mb = kbps / 1024f;
            if (mb < 10f)         return $"{mb:F1}M";                 // 1.0M … 9.9M
            if (mb < 1000f)       return $"{mb:F0}M";                 // 10M … 999M
            return $"{mb / 1024f:F1}G";
        }

        private string StripUnitForIcon(string metric, string fullText)
        {
            if (metric is "CPU" or "GPU" or "RAM" or "CPUTemp" or "GPUTemp" or "Battery")
                return fullText.TrimEnd('%', '°');
            if (fullText != "--" && _trayIconText.TryGetValue(metric, out var compact))
                return compact;   // speeds ("1.2M") and battery time ("2:15")
            return fullText; // CPUFreq (G/M), "--", "AC" stay unchanged
        }

        private System.Drawing.Icon RenderSensorIcon(string text, WpfColor wpfColor, string metric = "")
        {
            int size;
            try { size = Math.Max(16, System.Windows.Forms.SystemInformation.SmallIconSize.Width); }
            catch { size = 16; }

            System.Drawing.Color bg;
            if (metric is "CPUTemp" or "GPUTemp")
            {
                bool isWarmAmber = wpfColor.R == 245 && wpfColor.G == 158 && wpfColor.B == 11;
                bg = isWarmAmber
                    ? System.Drawing.Color.FromArgb(0x8C, 0x57, 0x00) // dark amber, ~6:1 contrast with white text
                    : System.Drawing.Color.FromArgb(wpfColor.R, wpfColor.G, wpfColor.B);
            }
            else if (wpfColor == _trayHotColor)  bg = System.Drawing.Color.FromArgb(0xC6, 0x2A, 0x2A); // hot  → red (universal, whatever the sensor)
            else if (wpfColor == _trayWarnColor) bg = System.Drawing.Color.FromArgb(0x8F, 0x4A, 0x07); // warn → dark orange (universal)
            else bg = metric switch
            {
                "CPU"     => System.Drawing.Color.FromArgb(0x1E, 0x50, 0xA5), // bright blue (the most used sensor)
                "GPU"     => System.Drawing.Color.FromArgb(0x38, 0x38, 0x40), // neutral dark grey
                "RAM"     => System.Drawing.Color.FromArgb(0x38, 0x3E, 0x38), // grey with a discreet green tint
                "CPUFreq" => System.Drawing.Color.FromArgb(0x35, 0x35, 0x3D), // neutral dark grey
                "Battery" => System.Drawing.Color.FromArgb(0x40, 0x3A, 0x2E), // grey with a discreet warm tint
                _         => System.Drawing.Color.FromArgb(0x1E, 0x50, 0xA5), // fallback — albastru
            };

            using var bmp = new System.Drawing.Bitmap(size, size, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
            using (var g = System.Drawing.Graphics.FromImage(bmp))
            {
                g.Clear(System.Drawing.Color.Transparent);

                // Fundal: dreptunghi rotunjit opac (colturi ~size/5, ca badge-urile Win11).
                int radius = Math.Max(2, size / 5);
                using (var path = new System.Drawing.Drawing2D.GraphicsPath())
                {
                    int d = radius * 2;
                    var r = new System.Drawing.Rectangle(0, 0, size - 1, size - 1);
                    path.AddArc(r.X, r.Y, d, d, 180, 90);
                    path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
                    path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
                    path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
                    path.CloseFigure();
                    g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
                    using var bgBrush = new System.Drawing.SolidBrush(bg);
                    g.FillPath(bgBrush, path);
                }

                // Text: ClearType on the opaque background above.
                g.SmoothingMode     = System.Drawing.Drawing2D.SmoothingMode.None;
                g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
                g.PixelOffsetMode   = System.Drawing.Drawing2D.PixelOffsetMode.None;

                var fmt = (System.Drawing.StringFormat)System.Drawing.StringFormat.GenericTypographic.Clone();
                fmt.Alignment     = System.Drawing.StringAlignment.Center;
                fmt.LineAlignment = System.Drawing.StringAlignment.Center;
                fmt.FormatFlags  |= System.Drawing.StringFormatFlags.NoWrap | System.Drawing.StringFormatFlags.NoClip;

                // Dynamic fit: measure at a reference font, scale to fill the usable area (size - 2: 1px margin, the glyphs do not go
                // into the rounded corners).
                const float refSize = 32f;
                float inner = size - 2f;
                float fitted;
                using (var refFont = new System.Drawing.Font("Segoe UI", refSize, System.Drawing.FontStyle.Bold, System.Drawing.GraphicsUnit.Pixel))
                {
                    var m = g.MeasureString(text, refFont, int.MaxValue, fmt);
                    float sw = m.Width  > 0 ? inner / m.Width  : 1f;
                    float sh = m.Height > 0 ? inner / m.Height : 1f;
                    fitted = refSize * Math.Min(sw, sh) * 0.98f;
                }
                using var font  = new System.Drawing.Font("Segoe UI", Math.Max(6f, fitted), System.Drawing.FontStyle.Bold, System.Drawing.GraphicsUnit.Pixel);
                using var brush = new System.Drawing.SolidBrush(System.Drawing.Color.White);
                g.DrawString(text, font, brush, new System.Drawing.RectangleF(0, 0, size, size), fmt);
            }

            // GetHicon() creates a "raw" GDI handle that Windows does NOT free by itself. Icon.FromHandle() does not own it (Dispose
            // on it would not call DestroyIcon) — so Clone() is used (an independent copy) and the raw handle is destroyed right
            // away. Without this, every tick would leak a GDI handle — a slow but certain leak.
            IntPtr hIcon = bmp.GetHicon();
            try
            {
                using var temp = System.Drawing.Icon.FromHandle(hIcon);
                return (System.Drawing.Icon)temp.Clone();
            }
            finally
            {
                DestroyIcon(hIcon);
            }
        }

        // Dark renderer for tray ContextMenuStrip
        private class TrayMenuRenderer : Forms.ToolStripProfessionalRenderer
        {
            public TrayMenuRenderer() : base(new TrayMenuColors()) { }

            protected override void OnRenderMenuItemBackground(Forms.ToolStripItemRenderEventArgs e)
            {
                if (e.Item.Selected)
                {
                    var r = new System.Drawing.Rectangle(4, 2, e.Item.Width - 8, e.Item.Height - 4);
                    using var br = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(45, 255, 255, 255));
                    e.Graphics.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
                    using var gp = new System.Drawing.Drawing2D.GraphicsPath();
                    int rad = 6;
                    gp.AddArc(r.X, r.Y, rad, rad, 180, 90);
                    gp.AddArc(r.Right - rad, r.Y, rad, rad, 270, 90);
                    gp.AddArc(r.Right - rad, r.Bottom - rad, rad, rad, 0, 90);
                    gp.AddArc(r.X, r.Bottom - rad, rad, rad, 90, 90);
                    gp.CloseFigure();
                    e.Graphics.FillPath(br, gp);
                }
                else
                {
                    e.Graphics.FillRectangle(new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(16, 20, 32)), e.Item.Bounds);
                }
            }
            protected override void OnRenderToolStripBackground(Forms.ToolStripRenderEventArgs e)
            {
                using var br = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(16, 20, 32));
                e.Graphics.FillRectangle(br, e.AffectedBounds);
            }
            protected override void OnRenderSeparator(Forms.ToolStripSeparatorRenderEventArgs e)
            {
                int y = e.Item.Height / 2;
                using var pen = new System.Drawing.Pen(System.Drawing.Color.FromArgb(45, 255, 255, 255));
                e.Graphics.DrawLine(pen, 8, y, e.Item.Width - 8, y);
            }
        }
        private class TrayMenuColors : System.Windows.Forms.ProfessionalColorTable
        {
            public override System.Drawing.Color MenuBorder => System.Drawing.Color.FromArgb(60, 100, 160, 255);
            public override System.Drawing.Color MenuItemBorder => System.Drawing.Color.Transparent;
            public override System.Drawing.Color MenuItemSelected => System.Drawing.Color.Transparent;
            public override System.Drawing.Color ToolStripDropDownBackground => System.Drawing.Color.FromArgb(16, 20, 32);
            public override System.Drawing.Color ImageMarginGradientBegin => System.Drawing.Color.FromArgb(16, 20, 32);
            public override System.Drawing.Color ImageMarginGradientMiddle => System.Drawing.Color.FromArgb(16, 20, 32);
            public override System.Drawing.Color ImageMarginGradientEnd => System.Drawing.Color.FromArgb(16, 20, 32);
        }

        private void RestoreFromTray()
        {
            Show();
            WindowState = WindowState.Normal;
            Activate();
            // Topmost pulse: forces the window in front even if another app has focus
            Topmost = true;
            Topmost = false;
        }

        private void UpdateTrayIcon(float? cpuTemp, float? cpuLoad)
        {
            // The tooltip and balloon notifications are handled by UpdateTrayIconWithTemp(); the icon is the live gauge
            // (MainWindow.Logo.cs).
            UpdateTrayGauge(cpuTemp, cpuLoad);
        }
    }
